// Builds online-offer-v4-figma.html (static, Figma-import-ready) from online-offer-v4.html.
// Run from this folder:  node export-figma.js
const fs = require("fs");
const src = fs.readFileSync("online-offer-v4.html", "utf8");
const cut = (s, a, b) => {
  const i = s.indexOf(a), j = s.indexOf(b, i + a.length);
  if (i < 0 || j < 0) throw new Error("marker not found: " + a);
  return s.slice(i + a.length, j);
};
const must = (s, a) => { if (!s.includes(a)) throw new Error("missing: " + a.slice(0, 70)); };

const css = cut(src, "\n    <style>", "\n    </style>");
const body = cut(src, "\n  <body>", "\n  </body>").replace(/<script>[\s\S]*?<\/script>\s*/g, "");

// Frame 2: alternative added + logo section open (summary totals for 250 bottles)
let added = body;
for (const [a, b] of [
  ['<details class="card logos-card logos-dd">', '<details class="card logos-card logos-dd" open>'],
  ['<div class="alt" id="alt">', '<div class="alt" id="alt" hidden>'],
  ['<article class="product product-added" id="altProduct" hidden>', '<article class="product product-added" id="altProduct">'],
  ['<div class="sum-row sum-added" id="sumAlt" hidden>', '<div class="sum-row sum-added" id="sumAlt">'],
  ['<dd id="sumVat">€ 49,30</dd>', '<dd id="sumVat">€ 200,80</dd>'],
  ['<dd id="sumExcl">€ 246,50</dd>', '<dd id="sumExcl">€ 1.004,00</dd>'],
  ['<strong id="sumTotal">€ 295,80</strong>', '<strong id="sumTotal">€ 1.204,80</strong>'],
]) { must(added, a); added = added.replace(a, b); }

// Frame 3: scrolled state, top section only (condensed header, progress bar unchanged)
const top = '<div class="top" id="top">';
must(body, top);
const scrolled = body.slice(body.indexOf(top), body.indexOf('<div class="page">'))
  .replace(top, '<div class="top is-condensed" id="top">');

const frame = (label, html) => `      <div>
        <div class="frame-label">${label}</div>
        <div class="frame">
${html}
        </div>
      </div>`;

fs.writeFileSync("online-offer-v4-figma.html", `<!doctype html>
<html lang="en">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>Loopper – Your offer (v4) – Figma export</title>
    <!--
      Figma-import version of online-offer-v4.html. Generated by export-figma.js; edit v4 and re-run instead of editing this file.
      Static: no page scripts (only Figma's capture script), nothing sticky, no transitions. Three 1440px frames side by side:
        1. Default (logo section closed, alternative not added)
        2. Alternative added + logo section open (summary totals updated)
        3. Scrolled: condensed header (progress bar keeps its size)
    -->
    <!-- Figma capture (push to Figma): only acts when the URL has a #figmacapture=… hash -->
    <script src="https://mcp.figma.com/mcp/html-to-design/capture.js" async></script>
    <link rel="preconnect" href="https://fonts.googleapis.com" />
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
    <link href="https://fonts.googleapis.com/css2?family=Nunito:wght@400;500;600;700;800&display=swap" rel="stylesheet" />
    <style>${css}
      /* ---------- Figma export overrides ---------- */
      *, *::before, *::after { transition: none !important; }
      body { background: #d9dee4; }
      .canvas { display: flex; align-items: flex-start; gap: 80px; width: max-content; padding: 60px; }
      .frame-label { margin-bottom: 12px; font-size: 14px; font-weight: 800; letter-spacing: 0.04em; color: #5b6672; }
      .frame { width: 1440px; overflow: hidden; background: #fff; }
      .top, .top .stepper-bar, .side { position: static; }
      .side { max-height: none; overflow: visible; }
    </style>
  </head>
  <body>
    <div class="canvas">
${frame("1 · DEFAULT · 1440", body)}
${frame("2 · ALTERNATIVE ADDED + LOGO SECTION OPEN · 1440", added)}
${frame("3 · SCROLLED · CONDENSED HEADER · 1440", scrolled)}
    </div>
  </body>
</html>
`);
console.log("wrote online-offer-v4-figma.html");
